@lru_cache(512)
def trading_time_to_str(trading_time):
    return ', '.join(['%02d:%02d-%02d:%02d' % (divmod(s, 60) + divmod(e, 60)) for s, e in trading_time])
@lru_cache(512)
def get_trading_schedule(trading_time, is_backtest=True):
    time_set = set()
    start_time_delta = int(is_backtest)
    for s, e in trading_time:
        if s > e:
            for i in range(s + start_time_delta, 1440):
                time_set.add(divmod(i, 60))
            for i in range(0, e + 1):
                time_set.add(divmod(i, 60))
        else:
            for i in range(s + start_time_delta, e + 1):
                time_set.add(divmod(i, 60))
    else:
        return time_set
@lru_cache(512)
def get_trading_time_tuple(trading_time):
    _trading_time_list = list()
    for tuple_time in trading_time:
        if tuple_time[0] > tuple_time[1]:
            _trading_time_list.append((tuple_time[0], 1440))
            _trading_time_list.append((0, tuple_time[1]))
            continue
        _trading_time_list.append(tuple_time)
        continue
    if len(_trading_time_list) > 0:
        return tuple(_trading_time_list)
    else:
        return trading_time
def is_stock_trade_time_now(now=None):
    if now is None:
        now = datetime.datetime.now().time()
    return STOCK_AM_OPEN < now < STOCK_AM_CLOSE or STOCK_PM_OPEN < now < STOCK_PM_CLOSE
def is_future_trade_time_now(now=None):
    if now is None:
        now = datetime.datetime.now().time()
    return FUTURE_AM_OPEN < now < FUTURE_AM_CLOSE or FUTURE_PM_OPEN < now < FUTURE_PM_CLOSE
def is_stock_trade_trigger(am_open, am_close, pm_open, pm_close, pm_over, freq, now=None):
    """
    根据输入schedule判断是否在交易时间内
    :param now:
    :param am_open:
    :param am_close:
    :param pm_open:
    :param pm_close:
    :param pm_over:
    :param freq:
    :return:
    """
    if now is None:
        now = datetime.datetime.now().time()
    if freq == Frequency.DAILY.value:
        now_date = datetime.date.today()
        time_delta = datetime.timedelta(microseconds=10)
        delay_delta = datetime.timedelta(minutes=5)
        now_timestamp = datetime.datetime.combine(now_date, now)
        pm_over_timestamp = datetime.datetime.combine(now_date, pm_over)
        if now_timestamp - time_delta > pm_over_timestamp and pm_over_timestamp + delay_delta > now_timestamp:
            return True
        return False
    else:
        return am_open <= now < am_close or pm_open <= now < pm_close
def is_future_trade_trigger(am_open, am_close, pm_open, pm_close, pm_over, freq, now=None):
    """
    根据输入schedule判断是否在交易时间内
    :param now:
    :param am_open:
    :param am_close:
    :param pm_open:
    :param pm_close:
    :param pm_over:
    :param freq:
    :return:
    """
    if now is None:
        now = datetime.datetime.now().time()
    if freq == Frequency.DAILY.value:
        now_date = datetime.date.today()
        time_delta = datetime.timedelta(microseconds=10)
        delay_delta = datetime.timedelta(minutes=5)
        now_timestamp = datetime.datetime.combine(now_date, now)
        pm_over_timestamp = datetime.datetime.combine(now_date, pm_over)
        if now_timestamp - time_delta > pm_over_timestamp and pm_over_timestamp + delay_delta > now_timestamp:
            return True
        return False
    else:
        return am_open < now < am_close or pm_open < now < pm_close
